import * as D from './domain.js';
import * as Store from './storage.js';
import { parseBackup, MAX_BACKUP_BYTES } from './backup.js';
import * as Sync from './sync.js';
(() => {
'use strict';
const KEY='focusflow.workspace.v2',OLD='focusflow.tasks.v1',$=id=>document.getElementById(id),view=$('page-view'),modal=$('modal'),form=$('modal-form');
const uid=()=>crypto.randomUUID?.()||`${Date.now()}-${Math.random().toString(16).slice(2)}`;
const iso=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const today=()=>iso(),plus=(s,n)=>{const d=new Date(`${s}T12:00:00`);d.setDate(d.getDate()+n);return iso(d)};
const fresh=()=>({version:2,profile:{name:'Student',language:'English'},settings:{theme:'light',focusMinutes:25,breakMinutes:5,alerts:false},tasks:[],schedule:[],sessions:[],notes:[],revisions:[],subjects:[],exams:[],goals:{dailyMinutes:120,weeklySessions:10,monthlyTopics:20},timer:{mode:'focus',running:false,duration:1500,remaining:1500,endAt:0,startedAt:0,elapsed:0,rounds:0,taskId:''},ui:{page:'dashboard',range:'week',date:today(),taskQuery:'',status:'all',priority:'all',taskSubject:'all',taskDue:'all',noteQuery:'',coachText:'',coachTopic:''}});
let db=fresh(),toastTimer,timerLoop=null,wakeLock=null,noteAutosave=null,formType='',editId='',extra={},syncMessage='',syncSession=null,syncPending=null;
const save=async()=>{try{await Store.saveWorkspace(db);return true}catch(e){console.error(e);toast('Could not save planner data. Export a backup if storage remains unavailable.');return false}};
const toast=s=>{const x=$('toast');x.textContent=s;x.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>x.classList.remove('show'),2500)};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dateText=s=>{if(!s)return 'No date';const [y,m,d]=s.split('-').map(Number);return new Intl.DateTimeFormat(undefined,{month:'short',day:'numeric'}).format(new Date(y,m-1,d))};
const longDate=s=>{if(!s)return '';const [y,m,d]=s.split('-').map(Number);return new Intl.DateTimeFormat(undefined,{weekday:'short',month:'short',day:'numeric'}).format(new Date(y,m-1,d))};
const late=t=>D.isOverdue(t,today()),mins=s=>Math.floor((s||0)/60),dur=s=>`${Math.floor((s||0)/3600)}h ${String(Math.floor((s||0)%3600/60)).padStart(2,'0')}m`;
const daysTo=s=>Math.max(0,Math.ceil((new Date(`${s}T12:00:00`)-new Date(`${today()}T12:00:00`))/86400000));
const topics=()=>db.subjects.flatMap(s=>s.chapters.flatMap(c=>c.topics));
const topicPct=()=>{const a=topics();return a.length?Math.round(a.filter(t=>t.status==='completed').length/a.length*100):0};
const b=(label,act,style='button-primary',attrs='')=>`<button class="button ${style}" type="button" data-action="${act}" ${attrs}>${label}</button>`;
const small=(label,act,id,style='button-quiet')=>`<button class="button ${style} button-small" type="button" data-action="${act}" data-id="${esc(id)}">${label}</button>`;
const head=(eye,title,sub,action='')=>`<div class="page-heading"><div><p class="eyebrow">${eye}</p><h1>${title}</h1><p>${sub}</p></div>${action?`<div class="heading-actions">${action}</div>`:''}</div>`;
const empty=(icon,title,sub,cta='',act='')=>`<div class="empty-state"><div class="empty-symbol">${icon}</div><strong>${title}</strong><p>${sub}</p>${cta?`<button class="link-button" data-action="${act}">${cta}</button>`:''}</div>`;
const card=(title,body,action='')=>`<section class="card"><div class="card-heading"><h2>${title}</h2>${action}</div>${body}</section>`;
const sel=(label,name,opts,value)=>`<div class="form-field"><label class="field-label" for="f-${name}">${label}</label><select class="control" id="f-${name}" name="${name}">${opts.map(([v,l])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`).join('')}</select></div>`;
const field=(label,name,value='',type='text',opts={})=>`<div class="form-field"><label class="field-label" for="f-${name}">${label}${opts.optional?' <span class="field-note">Optional</span>':''}</label>${type==='textarea'?`<textarea class="control" id="f-${name}" name="${name}" maxlength="${opts.max||1500}" ${opts.required?'required':''} placeholder="${esc(opts.placeholder||'')}">${esc(value)}</textarea>`:`<input class="control" id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${opts.required?'required':''} ${opts.min!=null?`min="${opts.min}"`:''} ${opts.max!=null?`max="${opts.max}"`:''} placeholder="${esc(opts.placeholder||'')}">`}</div>`;
const titles={dashboard:'Today',timetable:'Timetable',focus:'Focus timer',tasks:'Tasks',revisions:'Revision',syllabus:'Syllabus',exams:'Exams',notes:'Notes',analytics:'Progress',goals:'Goals & habits',assistant:'Study coach',settings:'Settings'};
function shell(){document.body.classList.toggle('dark',db.settings.theme==='dark');$('theme-toggle').setAttribute('aria-label',db.settings.theme==='dark'?'Switch to light theme':'Switch to dark theme');$('today-chip').textContent=new Intl.DateTimeFormat(undefined,{weekday:'short',month:'short',day:'numeric'}).format(new Date());$('current-page-label').textContent=titles[db.ui.page]||'Today';document.title=`FocusFlow — ${titles[db.ui.page]||'Study Planner'}`;document.querySelectorAll('[data-page]').forEach(x=>{const active=x.dataset.page===db.ui.page;x.classList.toggle('active',active);if(active)x.setAttribute('aria-current','page');else x.removeAttribute('aria-current')})}
function render(){shell();view.innerHTML=(pages[db.ui.page]||pages.dashboard)();if(db.ui.page==='focus')startTicker();else stopTicker()}
function resetScroll(){setTimeout(()=>window.scrollTo(0,0),50)}
function taskRows(list,compact=false){return list.length?`<div class="row-list">${list.map(t=>`<div class="list-row"><input type="checkbox" class="task-check" data-action="task-toggle" data-id="${esc(t.id)}" aria-label="Mark ${esc(t.title)} complete" ${t.completed?'checked':''}><div class="row-copy"><div class="row-title ${t.completed?'strike':''}">${esc(t.title)}</div><div class="row-subtitle">${esc(t.subject||'General')} · ${t.dueDate?`${late(t)?'Overdue · ':''}${dateText(t.dueDate)}`:'No deadline'} · ${esc(t.estimate||30)} min</div></div><span class="badge ${late(t)?'overdue':esc(t.priority)}">${late(t)?'Overdue':esc(t.priority)}</span>${compact?'':`<div class="row-actions">${small('Edit','task-edit',t.id)}${small('Delete','task-delete',t.id,'button-danger')}</div>`}</div>`).join('')}</div>`:empty('✓','No tasks here yet','Add one small next step to your plan.','Add a task','task-new')}
function scheduleRows(list,compact=false){return list.length?`<div>${list.map(s=>`<div class="calendar-item"><span class="calendar-time">${esc(s.time||'Anytime')}</span><div class="row-copy"><div class="row-title">${esc(s.subject)}${s.topic?` · ${esc(s.topic)}`:''}</div><div class="row-subtitle">${esc(s.chapter||'Study block')} · ${esc(s.duration||45)} min ${s.break?`· ${esc(s.break)} min break`:''}</div></div>${compact?'':`<div class="row-actions">${small('Edit','schedule-edit',s.id)}${small('×','schedule-delete',s.id,'button-danger')}</div>`}</div>`).join('')}</div>`:empty('▦','Your timetable has space','Add a study session with a topic and duration.','Add session','schedule-new')}
function revRows(list,compact=false){return list.length?`<div class="row-list">${list.map(r=>`<div class="list-row"><span class="stat-icon amber">↻</span><div class="row-copy"><div class="row-title">${esc(r.topic)}</div><div class="row-subtitle">${esc(r.subject)} · ${r.due<today()?'Overdue':r.due===today()?'Due today':dateText(r.due)}</div></div>${compact?'':small('Reviewed','revision-done',r.id,'button-primary')}</div>`).join('')}</div>`:empty('↻','Nothing due right now','Topics will appear here when a revision is due.')}
function examRows(list,compact=false){
  if(!list.length)return empty('⌁','No upcoming exams','Add an exam date to see it in your plan.','Add exam','exam-new');
  return '<div class="row-list">'+list.map(x=>{
    const countdown=x.date<today()?'Past':daysTo(x.date)===0?'Today':daysTo(x.date)+' days';
    const actions=compact?'':'<div class="row-actions">'+small('Edit','exam-edit',x.id)+small('Delete','exam-delete',x.id,'button-danger')+'</div>';
    return '<div class="list-row"><span class="stat-icon rose" aria-hidden="true">⌁</span><div class="row-copy"><div class="row-title">'+esc(x.title||x.subject)+'</div><div class="row-subtitle">'+esc(x.subject)+' · '+dateText(x.date)+(x.time?' · '+esc(x.time):'')+'</div></div><span class="badge '+(x.date<today()?'':'due')+'">'+countdown+'</span>'+actions+'</div>';
  }).join('')+'</div>';
}
function dashboard(){
  const pending=db.tasks.filter(t=>!t.completed).sort((a,b)=>(a.dueDate||'9999').localeCompare(b.dueDate||'9999'));
  const sessions=db.schedule.filter(s=>s.date===today()).sort((a,b)=>(a.time||'').localeCompare(b.time||''));
  const dueRevisions=db.revisions.filter(r=>!r.lastReview&&r.due<=today()).sort((a,b)=>a.due.localeCompare(b.due)).slice(0,3);
  const upcoming=db.exams.filter(e=>e.date>=today()).sort((a,b)=>a.date.localeCompare(b.date)).slice(0,2);
  const weekStart=plus(today(),-6),weekSessions=db.sessions.filter(s=>s.date>=weekStart&&s.date<=today());
  const weekSeconds=weekSessions.reduce((sum,s)=>sum+(s.seconds||0),0),completed=db.tasks.filter(t=>t.completed).length;
  const greeting=new Date().getHours()<12?'morning':new Date().getHours()<17?'afternoon':'evening';
  const name=db.profile.name&&db.profile.name!=='Student'?', '+esc(db.profile.name):'';
  const title=pending[0]?'Start with '+esc(pending[0].title)+'.':sessions.length?'Your study plan is ready.':'Make room for focused work.';
  const detail=pending[0]?(esc(pending[0].subject||'Study task')+(pending[0].dueDate?' · due '+dateText(pending[0].dueDate):'')):sessions.length?sessions.length+' session'+(sessions.length===1?'':'s')+' planned for today.':'Add a task or plan a session, then begin when you’re ready.';
  const nextTask=pending.length?taskRows(pending.slice(0,3),true):empty('✓','No open tasks','Add one small next step to your plan.','Add a task','task-new');
  const plan=sessions.length?scheduleRows(sessions,true):empty('▦','Nothing planned yet','Add a study block to give today a starting point.','Plan a session','schedule-new');
  const revisions=dueRevisions.length?revRows(dueRevisions,true):empty('↻','You’re up to date','Topics due for review will appear here.');
  const exams=upcoming.length?examRows(upcoming,true):empty('⌁','No exams added','Add a date to see your next countdown.','Add exam','exam-new');
  const summary='<section class="weekly-summary" aria-label="Study progress summary"><div class="weekly-summary-item"><span>Focused this week</span><strong>'+dur(weekSeconds)+'</strong></div><div class="weekly-summary-item"><span>Tasks complete</span><strong>'+completed+' of '+db.tasks.length+'</strong></div><div class="weekly-summary-item"><span>Syllabus covered</span><strong>'+topicPct()+'%</strong></div></section>';
  const columns='<div class="dashboard-layout"><div class="dashboard-column">'+card('Today’s plan',plan,'<button class="link-button" data-action="navigate" data-page="timetable">Open timetable</button>')+card('Revisions due',revisions,'<button class="link-button" data-action="navigate" data-page="revisions">View revisions</button>')+'</div><div class="dashboard-column">'+card('Next task',nextTask,'<button class="link-button" data-action="navigate" data-page="tasks">All tasks</button>')+card('Coming up',exams,'<button class="link-button" data-action="navigate" data-page="exams">All exams</button>')+'</div></div>';
  return head('TODAY · '+longDate(today()),'Good '+greeting+name+'.','A simple plan, one focused step at a time.')+'<section class="today-hero"><div><p class="eyebrow">YOUR NEXT STEP</p><h2>'+title+'</h2><p>'+detail+'</p></div><div class="heading-actions">'+b('Start studying','start-study')+b('＋ Add a task','task-new','button-quiet')+'</div></section>'+summary+columns;
}
function timetable(){const base=db.ui.date||today(),range=db.ui.range||'week';let from=base,to=base;if(range==='week'){const d=new Date(`${base}T12:00:00`);d.setDate(d.getDate()-d.getDay());from=iso(d);to=plus(from,6)}if(range==='month'){from=base.slice(0,7)+'-01';const d=new Date(`${from}T12:00:00`);d.setMonth(d.getMonth()+1);to=plus(iso(d),-1)}const list=db.schedule.filter(s=>s.date>=from&&s.date<=to).sort((a,b)=>a.date.localeCompare(b.date)||(a.time||'').localeCompare(b.time||''));return `${head('PLAN YOUR TIME','Study timetable','Arrange daily sessions, breaks, and focused blocks.',b('＋ Add session','schedule-new'))}<section class="card"><div class="card-heading"><div><h2>Study sessions</h2><p>${longDate(from)}${to!==from?` — ${longDate(to)}`:''}</p></div><div class="heading-actions"><div class="pill-tabs">${['day','week','month'].map(x=>`<button data-action="range" data-range="${x}" class="${range===x?'active':''}">${x[0].toUpperCase()+x.slice(1)}</button>`).join('')}</div><input class="control date-control" type="date" data-change="date" value="${esc(base)}" aria-label="Choose timetable date"></div></div>${list.length?`<div class="row-list">${list.map(s=>`<div class="calendar-item"><span class="calendar-time">${range==='day'?'':`${dateText(s.date)} · `}${esc(s.time||'Anytime')}</span><div class="row-copy"><div class="row-title">${esc(s.subject)}${s.topic?` · ${esc(s.topic)}`:''}</div><div class="row-subtitle">${esc(s.chapter||'Study session')} · ${esc(s.duration)} min${s.break?` + ${esc(s.break)} min break`:''}</div></div><div class="row-actions">${small('Edit','schedule-edit',s.id)}${small('×','schedule-delete',s.id,'button-danger')}</div></div>`).join('')}</div>`:empty('▦','A little room to plan','Build a daily, weekly, or monthly rhythm that suits you.','Plan a session','schedule-new')}</section><div class="grid grid-2" style="margin-top:14px">${card('Study + break','<p class="row-subtitle">Give focused work a clear end, then leave room to reset. Each session stores a planned break.</p>')}${card('Ready to focus',b('Start a focus session','navigate','button-primary','data-page="focus"')+'<p class="row-subtitle" style="margin-top:8px">The timer records actual focused time.</p>')}</div>`}
function clock(s){s=Math.max(0,Math.floor(s));return `${String(Math.floor(s/3600)).padStart(2,'0')}:${String(Math.floor(s%3600/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`}
function rem(){const t=db.timer;return t.mode==='stopwatch'?(t.running?t.elapsed+Math.floor((Date.now()-t.startedAt)/1000):t.elapsed):t.running?Math.max(0,Math.ceil((t.endAt-Date.now())/1000)):t.remaining}
function sessionRows(a){return a.length?`<div class="row-list">${a.map(s=>`<div class="list-row"><span class="stat-icon green">◉</span><div class="row-copy"><div class="row-title">${esc(s.task||'Study session')}</div><div class="row-subtitle">${dateText(s.date)} · ${dur(s.seconds)}</div></div><span class="badge complete">Focused</span></div>`).join('')}</div>`:empty('◉','Your study log is ready','Finish a focus session and it will show here.')}
function focus(){const t=db.timer,sec=rem(),task=db.tasks.find(x=>x.id===t.taskId),daily=db.sessions.filter(x=>x.date===today()).reduce((a,x)=>a+x.seconds,0);return `${head('FIND YOUR RHYTHM','Focus timer','One task, a little focus, then a proper break.',b(document.body.classList.contains('immersive')?'Exit focus view':'Enter focus view','focus-mode','button-quiet')) }<div class="grid grid-2"><section class="card timer-card"><div class="pill-tabs">${['focus','break','stopwatch'].map(m=>`<button data-action="timer-mode" data-mode="${m}" class="${t.mode===m?'active':''}">${m==='stopwatch'?'Stopwatch':m[0].toUpperCase()+m.slice(1)}</button>`).join('')}</div><div class="timer-face" id="timer-face">${clock(sec)}</div><div class="timer-mode" id="timer-subtitle">${t.running?'Session in progress':t.mode==='stopwatch'?'Track an open-ended session':`Ready for a ${t.mode==='focus'?db.settings.focusMinutes:db.settings.breakMinutes} minute ${t.mode} session`}</div><div class="timer-controls">${b(t.running?'Pause':'Start',t.running?'timer-pause':'timer-start')}${b('Reset','timer-reset','button-quiet')}${t.running?b('Finish now','timer-finish','button-quiet'):''}</div><div class="field-grid" style="text-align:left;margin-top:18px">${sel('Study task','taskId',[['','No task selected'],...db.tasks.filter(x=>!x.completed).map(x=>[x.id,x.title])],t.taskId)}${field('Focus length (minutes)','focus-length',db.settings.focusMinutes,'number',{min:1,max:180})}</div><p class="row-subtitle" style="text-align:left">Break length: ${db.settings.breakMinutes} min · Adjust defaults in Settings.</p></section><div class="grid">${card('Focused today',`<div class="progress-summary"><strong>${dur(daily)}</strong><span>${db.goals.dailyMinutes} min goal</span></div><div class="progress-track"><div class="progress-fill" style="width:${db.goals.dailyMinutes?Math.min(100,mins(daily)/db.goals.dailyMinutes*100):0}%"></div></div><p class="row-subtitle" style="margin-top:9px">${db.sessions.filter(x=>x.date===today()).length} completed focus sessions</p>`)}${card('One thing at a time',`<div class="focus-banner"><div><strong>${esc(task?.title||'Choose a task')}</strong><small>${esc(task?.subject||'Focus at your pace')}</small></div><span>✦</span></div><p class="row-subtitle" style="margin-top:10px">Pause whenever you need. FocusFlow logs completed time, not planned time.</p>`)}</div></div><section class="card" style="margin-top:14px">${card('Recent sessions',sessionRows(db.sessions.slice().sort((a,b)=>b.startedAt-a.startedAt).slice(0,5)))}</section>`}
function taskExtraFilters(){const ss=[...new Set(db.tasks.map(t=>t.subject).filter(Boolean))];return `<select class="control filter-control" data-change="task-subject" aria-label="Filter subject"><option value="all">All subjects</option>${ss.map(x=>`<option value="${esc(x)}" ${db.ui.taskSubject===x?'selected':''}>${esc(x)}</option>`).join('')}</select><select class="control filter-control" data-change="task-due" aria-label="Filter due date"><option value="all">All due dates</option><option value="upcoming" ${db.ui.taskDue==='upcoming'?'selected':''}>Next 7 days</option><option value="later" ${db.ui.taskDue==='later'?'selected':''}>Later</option><option value="no-date" ${db.ui.taskDue==='no-date'?'selected':''}>No due date</option></select>`}function tasksPage(){const list=D.filterTasks(db.tasks,{query:db.ui.taskQuery,status:db.ui.status,priority:db.ui.priority,subject:db.ui.taskSubject,due:db.ui.taskDue,sort:'due',today:today()});return `${head('YOUR NEXT STEPS','Tasks & homework','Assignments, practice, and projects in one place.',b('＋ Add task','task-new'))}<section class="card"><div class="toolbar"><label class="search-control"><span class="sr-only">Search tasks</span><input class="control" placeholder="Search task titles…" value="${esc(db.ui.taskQuery)}" data-input="task-query"></label><select class="control filter-control" data-change="status" aria-label="Filter tasks"><option value="all" ${db.ui.status==='all'?'selected':''}>All statuses</option><option value="pending" ${db.ui.status==='pending'?'selected':''}>Pending</option><option value="completed" ${db.ui.status==='completed'?'selected':''}>Completed</option><option value="overdue" ${db.ui.status==='overdue'?'selected':''}>Overdue</option></select><select class="control filter-control" data-change="priority" aria-label="Filter priority"><option value="all">All priorities</option>${['high','medium','low'].map(x=>`<option value="${x}" ${db.ui.priority===x?'selected':''}>${x[0].toUpperCase()+x.slice(1)} priority</option>`).join('')}</select>${taskExtraFilters()}<span class="row-subtitle">${list.length} shown · ${db.tasks.filter(t=>!t.completed).length} pending</span></div>${taskRows(list)}</section>`}
function revisions(){const all=db.revisions.slice().sort((a,b)=>a.due.localeCompare(b.due)),due=all.filter(r=>!r.due||r.due<=today()),future=all.filter(r=>r.due>today()),done=all.filter(r=>r.lastReview);return `${head('MAKE IT STICK','Revision planner','Return to topics at sensible intervals.',b('＋ Add revision','revision-new'))}<div class="grid grid-3"><article class="card stat-card"><div class="stat-label">Due today <span class="stat-icon amber">↻</span></div><strong>${due.filter(r=>r.due===today()).length}</strong><small>Ready for a short recall session</small></article><article class="card stat-card"><div class="stat-label">Overdue <span class="stat-icon rose">!</span></div><strong>${due.filter(r=>r.due<today()).length}</strong><small>One topic at a time</small></article><article class="card stat-card"><div class="stat-label">Scheduled <span class="stat-icon green">✓</span></div><strong>${future.length}</strong><small>Topics with a next review</small></article></div><div class="grid grid-2" style="margin-top:14px">${card('Ready to review',revRows(due))}${card('Coming up',revRows(future))}</div>${card('Recently reviewed',done.length?`<div class="row-list">${done.slice(-6).reverse().map(r=>`<div class="list-row"><span class="stat-icon green">✓</span><div class="row-copy"><div class="row-title">${esc(r.topic)}</div><div class="row-subtitle">${esc(r.subject)} · reviewed ${dateText(r.lastReview)}</div></div>${small('Review again','revision-reopen',r.id)}</div>`).join('')}</div>`:empty('↻','Your review history will show here','Complete a review to schedule its next interval.'))}`}
function syllabus(){const all=topics(),complete=all.filter(t=>t.status==='completed').length;return `${head('KNOW WHAT’S LEFT','Syllabus tracker','Break the syllabus into chapters and manageable topics.',b('＋ Add subject','subject-new'))}<div class="progress-summary"><strong>${topicPct()}% complete</strong><span>${complete} of ${all.length} topics · ${all.filter(t=>t.status==='in-progress').length} in progress</span></div><div class="progress-track" style="margin-bottom:15px"><div class="progress-fill" style="width:${topicPct()}%"></div></div>${db.subjects.length?`<div class="grid grid-2">${db.subjects.map(s=>{const a=s.chapters.flatMap(c=>c.topics),done=a.filter(t=>t.status==='completed').length;return `<section class="card subject-card" style="border-left-color:${esc(s.color)}"><div class="card-heading"><div><h2>${esc(s.name)}</h2><p>${done}/${a.length} topics · ${a.length?Math.round(done/a.length*100):0}%</p></div><div class="row-actions">${small('＋ Topic','topic-new',s.id)}${small('×','subject-delete',s.id,'button-danger')}</div></div>${s.chapters.length?s.chapters.map(c=>`<div><div class="row-title" style="margin:8px 0 3px">${esc(c.title)}</div>${c.topics.length?c.topics.map(t=>`<div class="topic-row"><span class="topic-name">${esc(t.title)}</span><select class="control" data-change="topic-status" data-subject="${esc(s.id)}" data-chapter="${esc(c.id)}" data-topic="${esc(t.id)}" aria-label="Status for ${esc(t.title)}"><option value="not-started" ${t.status==='not-started'?'selected':''}>Not started</option><option value="in-progress" ${t.status==='in-progress'?'selected':''}>In progress</option><option value="completed" ${t.status==='completed'?'selected':''}>Completed</option></select>${small('×','topic-delete',t.id,'button-danger')}</div>`).join(''):empty('·','No topics yet','Add a topic to begin.')}</div>`).join(''):empty('▤','No chapters yet','Add a topic with a chapter.','Add topic','topic-new',`data-id="${esc(s.id)}"`)}</section>`}).join('')}</div>`:empty('▤','Start with one subject','Add a subject, then break it into chapters and topics.','Add your first subject','subject-new')}`}
function exams(){const all=db.exams.slice().sort((a,b)=>a.date.localeCompare(b.date));return head('PLAN AHEAD','Exams','Keep your next important dates in view.',b('＋ Add exam','exam-new'))+card('Exam dates',examRows(all),all.length?'<span class="row-subtitle">'+all.length+' saved</span>':'')}
function safeLink(s){try{const u=new URL(s);return ['https:','http:'].includes(u.protocol)?u.href:'#'}catch{return '#'}}
function notes(){const q=db.ui.noteQuery.toLocaleLowerCase(),list=db.notes.filter(n=>!q||`${n.title} ${n.body} ${n.subject} ${n.chapter} ${n.topic}`.toLocaleLowerCase().includes(q));return `${head('KEEP IT CLOSE','Notes & materials','Save revision notes, checklists, and useful links.',b('＋ New note','note-new'))}<section class="card"><div class="toolbar"><label class="search-control"><span class="sr-only">Search notes</span><input class="control" placeholder="Search notes, subjects, topics…" value="${esc(db.ui.noteQuery)}" data-input="note-query"></label><span class="row-subtitle">${list.length} notes</span></div>${list.length?`<div class="grid grid-3">${list.map(n=>`<article class="card note-card"><div class="card-heading"><div class="row-title">${esc(n.title)}</div>${small('Edit','note-edit',n.id)}</div><div class="row-subtitle">${esc([n.subject,n.chapter,n.topic].filter(Boolean).join(' · ')||'General')}</div><div class="note-body" style="margin-top:8px">${esc(n.body||'No note text')}</div>${n.checklist?.length?`<div>${n.checklist.map((c,i)=>`<label class="topic-row"><input type="checkbox" data-action="note-check" data-id="${esc(n.id)}" data-index="${i}" ${c.done?'checked':''}><span class="topic-name ${c.done?'strike':''}">${esc(c.text)}</span></label>`).join('')}</div>`:''}<div class="note-bottom">${n.url?`<a class="link-button" href="${esc(safeLink(n.url))}" target="_blank" rel="noopener noreferrer">Open resource ↗</a>`:'<span></span>'}${small('Delete','note-delete',n.id,'button-danger')}</div></article>`).join('')}</div>`:empty('▧',q?'No matching notes':'Your notes start here','Keep key ideas and revision links together.','Create a note','note-new')}</section>`}
function analytics(){const ts=db.sessions.filter(s=>s.date===today()),ws=db.sessions.filter(s=>s.date>=plus(today(),-6)),ms=db.sessions.filter(s=>s.date.slice(0,7)===today().slice(0,7)),days=Array.from({length:7},(_,i)=>{const d=plus(today(),i-6);return {label:new Intl.DateTimeFormat(undefined,{weekday:'short'}).format(new Date(`${d}T12:00:00`)),sec:db.sessions.filter(s=>s.date===d).reduce((a,x)=>a+x.seconds,0)}}),max=Math.max(1,...days.map(x=>x.sec)),done=db.tasks.filter(t=>t.completed).length;return `${head('REAL PROGRESS','Progress & reports','A picture of the work you’ve actually logged.') }<div class="grid grid-4 dashboard-stats"><article class="card stat-card"><div class="stat-label">Today <span class="stat-icon">◉</span></div><strong>${dur(ts.reduce((a,s)=>a+s.seconds,0))}</strong><small>${ts.length} focus sessions</small></article><article class="card stat-card"><div class="stat-label">Last 7 days <span class="stat-icon green">↗</span></div><strong>${dur(ws.reduce((a,s)=>a+s.seconds,0))}</strong><small>${ws.length} completed sessions</small></article><article class="card stat-card"><div class="stat-label">This month <span class="stat-icon amber">▦</span></div><strong>${dur(ms.reduce((a,s)=>a+s.seconds,0))}</strong><small>${ms.length} focus sessions</small></article><article class="card stat-card"><div class="stat-label">Syllabus covered <span class="stat-icon rose">✓</span></div><strong>${topicPct()}%</strong><small>${topics().filter(t=>t.status==='completed').length} of ${topics().length} topics</small></article></div><div class="grid grid-2" style="margin-top:14px">${card('Daily focus · last 7 days',`<div class="chart">${days.map(x=>`<div class="chart-row"><span>${x.label}</span><div class="chart-track"><div class="chart-fill" style="width:${Math.round(x.sec/max*100)}%"></div></div><span class="chart-value">${x.sec?mins(x.sec)+'m':'—'}</span></div>`).join('')}</div><p class="row-subtitle" style="margin-top:12px">Hours are based on completed FocusFlow sessions only.</p>`)}${card('Tasks completed',`<div class="progress-summary"><strong>${done}/${db.tasks.length}</strong><span>${db.tasks.length?Math.round(done/db.tasks.length*100):0}% complete</span></div><div class="progress-track"><div class="progress-fill" style="width:${db.tasks.length?Math.round(done/db.tasks.length*100):0}%"></div></div><div class="chart" style="margin-top:17px">${[['Completed',done],['Pending',db.tasks.length-done],['Overdue',db.tasks.filter(late).length]].map(([l,n])=>`<div class="chart-row"><span>${l}</span><div class="chart-track"><div class="chart-fill" style="width:${db.tasks.length?Math.round(n/db.tasks.length*100):0}%"></div></div><span class="chart-value">${n}</span></div>`).join('')}</div>`)}${card('Recent study sessions',sessionRows(db.sessions.slice().sort((a,b)=>b.startedAt-a.startedAt).slice(0,7)))}${card('How to read this',`<p class="row-subtitle">Focus hours come from the timer. Syllabus and task progress use the items you entered. FocusFlow doesn’t invent hours or estimate activity outside the app.</p>`)}</div>`}
function streak(){let n=0,d=today();while(db.sessions.some(s=>s.date===d)){n++;d=plus(d,-1)}return n}
function goalCard(title,value,target,unit,caption){const p=target?Math.min(100,Math.round(value/target*100)):0;return `<article class="card"><div class="card-heading"><h2>${title}</h2><span class="stat-icon">✧</span></div><div class="progress-summary"><strong>${value} <small style="font-size:10px;color:var(--muted);font-weight:500">/ ${target} ${unit}</small></strong><span>${p}%</span></div><div class="progress-track"><div class="progress-fill" style="width:${p}%"></div></div><p class="row-subtitle">${caption}</p></article>`}
function goals(){const sec=db.sessions.filter(s=>s.date===today()).reduce((a,s)=>a+s.seconds,0),week=db.sessions.filter(s=>s.date>=plus(today(),-6)).length,month=topics().filter(t=>t.status==='completed'&&t.completedAt?.slice(0,7)===today().slice(0,7)).length;return `${head('SMALL WINS ADD UP','Goals & habits','Choose a kind target and notice the days you show up.',b('Edit goals','goals-edit','button-quiet'))}<div class="grid grid-3">${goalCard('Daily focused study',mins(sec),db.goals.dailyMinutes,'min',`${dur(sec)} focused today`)}${goalCard('Weekly focus sessions',week,db.goals.weeklySessions,'sessions',`${week} sessions in the last 7 days`)}${goalCard('Monthly topics completed',month,db.goals.monthlyTopics,'topics',`${month} syllabus topics completed`)}</div><div class="grid grid-2" style="margin-top:14px">${card('Your study rhythm',`<div class="milestone"><span class="milestone-icon">✦</span><div><strong>${streak()?`${streak()} study days in a row`:'Your next study day can start a streak'}</strong><small>A day counts after one logged focus session.</small></div></div><p class="row-subtitle">Missed days are just days. Your progress is still yours.</p>`)}${card('Milestones',`<div class="milestone"><span class="milestone-icon">◉</span><div><strong>${db.sessions.length} focus sessions logged</strong><small>Each completed session adds to your record.</small></div></div><div class="milestone"><span class="milestone-icon">▤</span><div><strong>${topics().filter(t=>t.status==='completed').length} syllabus topics complete</strong><small>${topicPct()}% of your tracked syllabus</small></div></div>`)}</div>`}
function coach(){return `${head('A STUDY BUDDY, NO API NEEDED','Study coach','Offline templates built from the subjects and exams you enter.') }<div class="focus-banner" style="margin-bottom:14px"><div><strong>Local study helpers</strong><small>Rule-based drafts, not a connected AI model. Check suggestions against your course material.</small></div><span class="offline-pill">NO NETWORK</span></div><div class="grid grid-2"><section class="card"><div class="card-heading"><div><h2>Pick a starting point</h2><p>Make a draft from a chapter or topic.</p></div></div>${field('Chapter or topic','coach-topic',db.ui.coachTopic,'text',{placeholder:'e.g. Photosynthesis'})}<div class="heading-actions" style="margin-top:12px;flex-wrap:wrap">${b('Break into tasks','coach-break')}${b('Practice questions','coach-questions','button-quiet')}${b('Revision checklist','coach-checklist','button-quiet')}${b('Plan around exams','coach-plan','button-quiet')}</div></section>${card('Coach draft',`<div class="coach-box"><div class="coach-label">RULE-BASED SUGGESTION · VERIFY BEFORE USE</div><div class="coach-output">${esc(db.ui.coachText||'Choose a study-coach tool to create a draft from the information you have entered.')}</div></div>`)}</div><div class="grid grid-3" style="margin-top:14px">${card('Can help','<p class="row-subtitle">Break work into small actions, write recall prompts, and suggest a schedule from your next exam date.</p>')}${card('Cannot verify facts','<p class="row-subtitle">Prompts are templates, not verified subject explanations or answer keys. Review them against your materials.</p>')}${card('Privacy','<p class="row-subtitle">No study notes or topics are sent to an AI service. This helper runs in your browser.</p>')}</div>`}
function settings(){return `${head('MAKE IT YOURS','Settings & data','Personalize your space and manage local planner data.') }<div class="grid grid-2"><section class="card"><div class="card-heading"><div><h2>Study preferences</h2><p>Profile, theme, and timer defaults.</p></div></div><form id="settings-form">${field('Display name','profileName',db.profile.name)}<div class="field-grid">${field('Focus session (minutes)','focusMinutes',db.settings.focusMinutes,'number',{min:1,max:180})}${field('Break (minutes)','breakMinutes',db.settings.breakMinutes,'number',{min:1,max:60})}${sel('Theme','theme',[['light','Light'],['dark','Dark']],db.settings.theme)}${sel('Language','language',[['English','English'],['Hindi','हिन्दी']],db.profile.language)}</div><div style="margin-top:14px"><button class="button button-primary">Save preferences</button></div></form></section>${card('Your data stays in browser storage',`<div class="setting-row"><div><strong>Export backup</strong><small>Download tasks, notes, sessions, and plans as JSON.</small></div>${b('Export JSON','export')}</div><div class="setting-row"><div><strong>Import backup</strong><small>Restore a FocusFlow JSON export (5 MB maximum).</small></div><label class="button button-quiet" for="import-file">Choose file<input id="import-file" type="file" accept="application/json,.json" hidden></label></div><div class="setting-row"><div><strong>Clear all planner data</strong><small>Removes data stored for this app in this browser.</small></div>${b('Clear data','clear-data','button-danger')}</div><p class="row-subtitle">Your plans are stored in this browser only. They are not encrypted or synced to other devices. Avoid storing highly sensitive information. Export a backup before clearing browser data or changing browsers.</p>`)}${card('Session reminders',`<div class="setting-row"><div><strong>In-app timer alerts</strong><small>Show a message when a timer ends; no browser permission is needed.</small></div><input type="checkbox" data-change="alerts" ${db.settings.alerts?'checked':''} aria-label="Enable in-app timer alerts"></div><p class="row-subtitle">No background reminders are sent.</p>`)}${card('Storage and sync',`<div class="setting-row"><div><strong>Storage</strong><small>Browser IndexedDB · FocusFlow local database</small></div><span class="badge complete">On device</span></div><div class="setting-row"><div><strong>Sign-in and cloud sync</strong><small>Not configured in this local-first edition.</small></div><span class="badge">Offline</span></div>`)}</div>`}
const localSettingsPage=settings;
settings=function(){let html=localSettingsPage().replace('Not configured in this local-first edition.','Optional sync is available after you configure a provider below.').replace('Your plans are stored in this browser only. They are not encrypted or synced to other devices.','Your local copy stays on this device. Optional cloud sync stores a copy with the provider you choose; it is not end-to-end encrypted.').replace('<span class="badge">Offline</span>','<span class="badge">Local by default</span>');const end=html.lastIndexOf('</div>');return end<0?html:`${html.slice(0,end)}${syncPanel()}${html.slice(end)}`};
function syncPanel(){const config=Sync.loadSyncConfig(),user=syncSession?.user;const remote=syncPending?.remote;const local=syncPending?.local;const status=syncMessage|| (user?`Signed in as ${esc(user.email||'your account')}. Local edits stay local until you choose a sync action.`:config?'Project settings saved in this browser. Sign in to review your cloud workspace.':'Not connected. Your planner continues to work on this device.');const preview=syncPending?`<div class="sync-warning" role="status"><strong>Review before changing either copy.</strong><p>On this device: ${workspaceCount(local)} planner records. In cloud: ${remote?workspaceCount(remote.workspace):'no workspace yet'}${remote?` · updated ${esc(new Date(remote.updated_at).toLocaleString())}`:''}.</p>${remote&&sameWorkspace(local,remote.workspace)?'<p>The copies match.</p>':`<p>${remote?'Choose which full workspace to keep. The other copy will be backed up as a JSON download first.':'This will create your first cloud copy; local records stay on this device.'}</p><div class="sync-actions">${b('Upload this device','sync-upload')}${remote?b('Restore cloud copy here','sync-download','button-quiet'):''}</div>`}</div>`:'';return card('Optional cloud sync',`<p class="row-subtitle">Supabase Auth and a private per-user Postgres row. Planner data is stored by Supabase and is not end-to-end encrypted. Sign-in and sync are opt-in; local planning remains available offline.</p><form id="sync-config-form" class="sync-form">${field('Supabase project URL','sync-url',config?.url||'','url',{required:true,placeholder:'https://your-project.supabase.co'})}${field('Publishable key or legacy anon key','sync-public-key',config?.publicKey||'','text',{required:true,placeholder:'Never enter a service-role or secret key'})}<button class="button button-quiet" type="submit">Save provider settings</button></form><p class="row-subtitle">Use only the project URL and public key shown in Supabase. The public key is not a database password. The app never needs a service-role key.</p>${config&&!user?`<form id="sync-auth-form" class="sync-form">${field('Email','sync-email',user?.email||'','email',{required:true})}${field('Password (12 or more characters)','sync-password','','password',{required:true})}<div class="sync-actions"><button class="button button-primary" type="button" data-action="sync-signin">Sign in</button><button class="button button-quiet" type="button" data-action="sync-signup">Create account</button></div></form>`:''}<p class="sync-state row-subtitle" role="status" aria-live="polite">${status}</p>${user?`<div class="sync-actions">${b('Review local and cloud copies','sync-preview')}${b('Sign out','sync-signout','button-quiet')}${syncPending&&remote?b('Download cloud backup','sync-export','button-quiet'):''}${remote?b('Delete cloud planner data','sync-delete','button-danger'):''}</div>${preview}<p class="row-subtitle">Signing out keeps this device’s data. Deleting cloud planner data does not delete your Supabase login; account deletion must be completed in Supabase after exporting anything you need.</p>`:''}<p class="sync-warning">Before the first upload or download, export a local backup. Cloud sync never runs automatically; use “Review” to see both copies and explicitly choose an upload or restore.</p>`)}
function sameWorkspace(a,b){const stable=v=>Array.isArray(v)?v.map(stable):v&&typeof v==='object'?Object.fromEntries(Object.keys(v).sort().map(k=>[k,stable(v[k])])):v;return JSON.stringify(stable(a))===JSON.stringify(stable(b))}
function workspaceCount(value){const primary=['tasks','schedule','notes','exams','revisions','sessions'].reduce((n,k)=>n+(Array.isArray(value?.[k])?value[k].length:0),0),syllabus=(value?.subjects||[]).reduce((n,s)=>n+1+(s.chapters||[]).reduce((c,ch)=>c+1+(ch.topics||[]).length,0),0);return primary+syllabus}
function downloadWorkspace(value,name){const blob=new Blob([JSON.stringify({app:'FocusFlow',version:2,exportedAt:new Date().toISOString(),data:value},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`focusflow-${name}-${today()}.json`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function requireSyncSession(){const session=await Sync.currentUser();syncSession=session;if(!session)throw Error('Sign in to continue. Local planner data is unchanged.');return session}
async function reviewSync(){try{if(!navigator.onLine)throw Error('You are offline. Your local planner is available; reconnect to review cloud sync.');const session=await requireSyncSession(),cloud=await Sync.getCloudWorkspace(session);const remote=cloud?{...cloud,workspace:parseBackup(JSON.stringify(cloud.workspace))}:null;syncPending={session,remote,local:structuredClone(db)};syncMessage=remote&&sameWorkspace(syncPending.local,remote.workspace)?'Your local and cloud copies match.':remote?'Both copies are available. Choose one after reviewing the record counts.':'No cloud workspace exists yet. You can upload this device after backing up.';render()}catch(error){syncMessage=error.message||'Could not review sync.';render()}}
async function syncUpload(){try{const session=await requireSyncSession();if(!syncPending)throw Error('Review the copies first.');if(!sameWorkspace(db,syncPending.local)){syncMessage='Local data changed since the review. Review the copies again before syncing.';syncPending=null;render();return}const fresh=await Sync.getCloudWorkspace(session);if((fresh?.revision??null)!==(syncPending.remote?.revision??null)){syncMessage='Cloud data changed since the review. Review the copies again before syncing.';syncPending=null;render();return}if(!confirm(`Upload ${workspaceCount(db)} planner records from this device to ${new URL(Sync.loadSyncConfig().url).hostname}?${fresh?' A backup of the current cloud copy will be downloaded first.':''} Your local copy will remain.`))return;if(fresh)downloadWorkspace(fresh.workspace,'cloud-before-upload');await Sync.putCloudWorkspace(session,parseBackup(JSON.stringify(db)),fresh?.revision??null);Sync.recordSyncSuccess();syncPending=null;syncMessage='Cloud copy updated. Your local planner remains available.';await reviewSync()}catch(error){syncMessage=error.message||'Upload did not complete.';syncPending=null;render()}}
async function syncDownload(){try{const session=await requireSyncSession();if(!syncPending?.remote)throw Error('Review the copies first.');const fresh=await Sync.getCloudWorkspace(session);if(!fresh||fresh.revision!==syncPending.remote.revision){syncMessage='Cloud data changed since the review. Review the copies again before restoring.';syncPending=null;render();return}if(!confirm(`Download a recovery backup of this device, then replace its planner with the cloud copy (${workspaceCount(fresh.workspace)} records)?`))return;downloadWorkspace(db,'local-before-restore');const previous=db;db=normalizeWorkspace(parseBackup(JSON.stringify(fresh.workspace)));if(!await save()){db=previous;throw Error('The cloud copy could not be saved locally. The recovery backup was downloaded.')};Sync.recordSyncSuccess();syncPending=null;syncMessage='Cloud copy restored to this device. A recovery backup was downloaded.';render()}catch(error){syncMessage=error.message||'Restore did not complete.';render()}}
async function syncDelete(){try{const session=await requireSyncSession(),cloud=await Sync.getCloudWorkspace(session);if(!cloud)throw Error('No cloud workspace exists.');if(!confirm('Download a JSON backup, then permanently delete this account’s synced planner row? This does not delete the Supabase account.'))return;downloadWorkspace(cloud.workspace,'cloud-before-delete');await Sync.deleteCloudWorkspace(session,cloud.revision);Sync.clearLastSync();syncPending=null;syncMessage='Synced planner data deleted. Your local planner and account remain.';render()}catch(error){syncMessage=error.message||'Cloud data was not deleted.';render()}}
async function syncAuth(kind){try{const email=$('f-sync-email')?.value||'',password=$('f-sync-password')?.value||'';if(kind==='signup'){const result=await Sync.signUp(email,password);if(result.confirmationRequired){syncMessage='Account created. Check your email to confirm, then sign in. The default provider email sender is rate-limited.';render();return}}else await Sync.signIn(email,password);syncSession=await Sync.currentUser();if(!syncSession)throw Error('Sign-in needs confirmation or has expired. Check your email, then sign in again.');syncPending=null;syncMessage=`Signed in as ${syncSession.user.email||'your account'}. No planner data has been uploaded.`;render()}catch(error){syncMessage=error.message||'Authentication did not complete.';render()}}
const originalSyncPanel=syncPanel;
syncPanel=()=>originalSyncPanel().replace('<button class="button button-quiet" type="submit">Save provider settings</button></form>','<button class="button button-quiet" type="submit">Save provider settings</button>'+(Sync.loadSyncConfig()?b('Remove provider settings','sync-clear-config','button-quiet'):'')+'</form>');
const panelBeforeMessageEscape=syncPanel;
syncPanel=()=>{const markup=panelBeforeMessageEscape();return syncMessage?markup.replace(syncMessage,()=>esc(syncMessage)):markup};
const syncPanelWithOriginGate=syncPanel;
syncPanel=()=>location.hostname.toLowerCase().endsWith('.github.io')?card('Cloud sync unavailable on GitHub Pages','<p class="sync-warning">GitHub Pages project sites share browser storage, so cloud sign-in is disabled on this host. Your local planner still works. Use the separate <a href="https://focusflow-study-planner.pages.dev/" target="_blank" rel="noopener noreferrer">Cloudflare Pages site</a> for optional cloud sync.</p>'):syncPanelWithOriginGate();
const syncPanelBeforeLastSuccess=syncPanel;
syncPanel=()=>{let markup=syncPanelBeforeLastSuccess(),at=Sync.lastSyncAt();if(syncSession&&at){const notice=`<p class="row-subtitle">Last successful sync: ${esc(new Date(at).toLocaleString())}</p>`;markup=markup.replace('<p class="sync-warning">Before the first upload',`${notice}<p class="sync-warning">Before the first upload`)}return markup};
const renderWithSyncSession=render;
render=function(){if(!Sync.sessionSnapshot())syncSession=null;renderWithSyncSession()};
const pages={dashboard,timetable,focus,tasks:tasksPage,revisions,syllabus,exams,notes,analytics,goals,assistant:coach,settings};
function getItem(type,id){const group={task:'tasks',schedule:'schedule',revision:'revisions',note:'notes',exam:'exams'}[type];if(group)return db[group].find(x=>x.id===id);if(type==='topic'){for(const s of db.subjects)for(const c of s.chapters){const t=c.topics.find(x=>x.id===id);if(t)return {...t,subjectId:s.id,chapter:c.title}}}return null}
function openForm(type,id='',more={}){formType=type;editId=id;extra=more;const item=id?getItem(type,id):null;$('modal-error').textContent='';$('modal-title').textContent=(id?'Edit ':'Add ')+({task:'task',schedule:'study session',revision:'revision topic',note:'study note',exam:'exam',subject:'subject',topic:'syllabus topic',goals:'study goals'}[type]||'item');$('modal-submit').textContent=id?'Save changes':'Save';let html='';
 if(type==='task')html=`${field('Task or assignment title','title',item?.title||'','text',{required:true,max:140,placeholder:'e.g. Finish algebra problem set'})}${field('Details','description',item?.description||'','textarea',{optional:true,placeholder:'What does done look like?'})}<div class="field-grid">${field('Subject','subject',item?.subject||'','text',{optional:true,max:48})}${field('Due date','dueDate',item?.dueDate||'','date')}${sel('Priority','priority',[['low','Low'],['medium','Medium'],['high','High']],item?.priority||'medium')}${field('Estimate (minutes)','estimate',item?.estimate||30,'number',{min:5,max:1440})}</div>`;
 if(type==='schedule')html=`<div class="field-grid">${field('Subject','subject',item?.subject||'','text',{required:true,max:48,placeholder:'e.g. Chemistry'})}${field('Date','date',item?.date||today(),'date',{required:true})}${field('Start time','time',item?.time||'09:00','time')}${field('Study duration (minutes)','duration',item?.duration||45,'number',{min:5,max:360})}${field('Chapter','chapter',item?.chapter||'','text',{optional:true,max:120})}${field('Topic','topic',item?.topic||'','text',{optional:true,max:120})}${field('Break (minutes)','break',item?.break??5,'number',{min:0,max:60})}</div>`;
 if(type==='revision')html=`<div class="field-grid">${field('Subject','subject',item?.subject||'','text',{required:true,max:48})}${field('Topic to revise','topic',item?.topic||'','text',{required:true,max:120})}${field('Next review date','due',item?.due||today(),'date',{required:true})}${sel('Starting interval','interval',[[1,'1 day'],[3,'3 days'],[7,'7 days'],[14,'14 days'],[30,'30 days']],item?.interval||1)}</div><p class="row-subtitle">Mark each review complete to schedule the next interval.</p>`;
 if(type==='note')html=`${field('Note title','title',item?.title||'','text',{required:true,max:120})}<div class="field-grid">${field('Subject','subject',item?.subject||'','text',{optional:true,max:48})}${field('Chapter','chapter',item?.chapter||'','text',{optional:true,max:100})}${field('Topic','topic',item?.topic||'','text',{optional:true,max:100})}${field('Useful link','url',item?.url||'','url',{optional:true,placeholder:'https://…'})}</div>${field('Notes','body',item?.body||'','textarea',{optional:true,max:5000,placeholder:'Capture what you want to remember…'})}${field('Checklist (one item per line)','checklist',(item?.checklist||[]).map(x=>x.text).join('\n'),'textarea',{optional:true,max:1200,placeholder:'Recall the key definition\nTry one practice question'})}`;
 if(type==='exam')html=`<div class="field-grid">${field('Exam name','title',item?.title||'','text',{required:true,max:120})}${field('Subject','subject',item?.subject||'','text',{required:true,max:48})}${field('Exam date','date',item?.date||'','date',{required:true})}${field('Time','time',item?.time||'','time')}</div>${field('Preparation notes','notes',item?.notes||'','textarea',{optional:true,max:500})}`;
 if(type==='subject')html=`${field('Subject name','name','','text',{required:true,max:48,placeholder:'e.g. Biology'})}${field('Color','color','#6357e8','color')}`;
 if(type==='topic'){const sid=more.subjectId||item?.subjectId||'',s=db.subjects.find(x=>x.id===sid);html=`${s?`<input type="hidden" name="subjectId" value="${esc(sid)}"><p class="row-subtitle">Subject: ${esc(s.name)}</p>`:sel('Subject','subjectId',db.subjects.map(x=>[x.id,x.name]),sid)}${field('Chapter','chapter',item?.chapter||'','text',{required:true,max:100,placeholder:'e.g. Cell structure'})}${field('Topic','topic',item?.title||'','text',{required:true,max:120,placeholder:'e.g. Mitosis'})}`}
 if(type==='goals')html=`<div class="field-grid">${field('Daily study target (minutes)','dailyMinutes',db.goals.dailyMinutes,'number',{min:1,max:1440})}${field('Weekly focus sessions','weeklySessions',db.goals.weeklySessions,'number',{min:1,max:100})}${field('Monthly topics completed','monthlyTopics',db.goals.monthlyTopics,'number',{min:1,max:500})}</div>`;
 $('modal-fields').innerHTML=html;modal.showModal();modal.querySelector('input:not([type=hidden]),textarea,select')?.focus()}
function saveForm(e){e.preventDefault();if(formType==='note'){clearTimeout(noteAutosave);noteAutosave=null}const v=n=>form.elements.namedItem(n)?.value?.trim()||'',err=$('modal-error');if(formType==='goals'){db.goals={dailyMinutes:+v('dailyMinutes')||120,weeklySessions:+v('weeklySessions')||10,monthlyTopics:+v('monthlyTopics')||20};save();modal.close();render();toast('Goals updated');return}
 if(formType==='task'){const d={title:v('title'),description:v('description'),subject:v('subject'),dueDate:v('dueDate'),priority:v('priority')||'medium',estimate:Math.max(5,+v('estimate')||30)};try{if(editId)D.updateTask(db.tasks,editId,d);else D.createTask(db.tasks,d,uid,Date.now)}catch(error){err.textContent=error.message;return}}
 if(formType==='schedule'){if(!v('subject')||!v('date')){err.textContent='Add a subject and date for this session.';return}const candidate={subject:v('subject'),date:v('date'),time:v('time'),duration:+v('duration')||45,chapter:v('chapter'),topic:v('topic'),break:+v('break')||0};const conflicts=D.scheduleConflicts(db.schedule,candidate,editId);if(conflicts.length&&!confirm(`This overlaps another session (${conflicts[0].subject} at ${conflicts[0].time}). Save it anyway?`))return;put('schedule',candidate)}
 if(formType==='revision'){if(!v('subject')||!v('topic')){err.textContent='Add a subject and topic to revise.';return}put('revisions',{subject:v('subject'),topic:v('topic'),due:v('due')||today(),interval:+v('interval')||1,step:0,lastReview:''})}
 if(formType==='note'){if(!v('title')){err.textContent='Give this note a title.';return}const url=v('url');if(url&&safeLink(url)==='#'){err.textContent='Use a valid http or https resource link.';return}const old=editId?db.notes.find(n=>n.id===editId):null,lines=v('checklist').split(/\r?\n/).map(x=>x.trim()).filter(Boolean),checklist=lines.map(text=>({text,done:old?.checklist?.find(x=>x.text===text)?.done||false}));upsertNote({title:v('title'),subject:v('subject'),chapter:v('chapter'),topic:v('topic'),url,body:v('body'),checklist})}
 if(formType==='exam'){if(!v('title')||!v('subject')||!v('date')){err.textContent='Add an exam name, subject, and date.';return}put('exams',{title:v('title'),subject:v('subject'),date:v('date'),time:v('time'),notes:v('notes')})}
 if(formType==='subject'){if(!v('name')){err.textContent='Enter a subject name.';return}db.subjects.push({id:uid(),name:v('name'),color:v('color')||'#6357e8',chapters:[]})}
 if(formType==='topic'){const s=db.subjects.find(x=>x.id===v('subjectId'));if(!s){err.textContent='Choose a subject first.';return}if(!v('chapter')||!v('topic')){err.textContent='Add a chapter and a topic.';return}let c=s.chapters.find(x=>x.title.toLocaleLowerCase()===v('chapter').toLocaleLowerCase());if(!c){c={id:uid(),title:v('chapter'),topics:[]};s.chapters.push(c)}c.topics.push({id:uid(),title:v('topic'),status:'not-started',createdAt:Date.now()})}
 save();formType='';modal.close();render();toast(editId?'Changes saved':'Added to your plan')}
function upsertNote(d){const id=editId||uid(),i=db.notes.findIndex(n=>n.id===id);if(i>=0)db.notes[i]={...db.notes[i],...d};else db.notes.unshift({id,...d});editId=id}
function put(group,d){if(editId){const i=db[group].findIndex(x=>x.id===editId);if(i>=0)db[group][i]={...db[group][i],...d}}else db[group].unshift({id:uid(),...d})}
function deleteItem(group,id,label){if(!confirm(`Delete this ${label}? This cannot be undone.`))return;if(group==='tasks')D.deleteTask(db.tasks,id);else db[group]=db[group].filter(x=>x.id!==id);save();render();toast(`${label[0].toUpperCase()+label.slice(1)} deleted`)}
function toggleTask(id,on){if(!D.toggleTask(db.tasks,id,on))return;save();render();toast(on?'Task completed':'Task reopened')}
function revisionDone(id){const r=db.revisions.find(x=>x.id===id);if(!r)return;r.lastReview=today();const next=D.nextReview(r);r.step=next.step;r.interval=next.interval;r.due=plus(today(),r.interval);save();render();toast(`Next review set for ${dateText(r.due)}`)}
function setMode(mode){if(db.timer.running)pauseTimer(false);const n=(mode==='break'?db.settings.breakMinutes:db.settings.focusMinutes)*60;db.timer={...db.timer,mode,running:false,duration:n,remaining:mode==='stopwatch'?0:n,endAt:0,startedAt:0,elapsed:0};save();render()}
function startTimer(){const t=db.timer;if(t.running)return;if(t.mode==='stopwatch')t.startedAt=Date.now();else{if(t.remaining<=0)t.remaining=t.duration;t.endAt=Date.now()+t.remaining*1000;t.startedAt=Date.now()}t.running=true;save();render()}
function pauseTimer(rerender=true){const t=db.timer;if(!t.running)return;if(t.mode==='stopwatch')t.elapsed+=Math.floor((Date.now()-t.startedAt)/1000);else{t.remaining=rem();t.elapsed=t.duration-t.remaining;t.endAt=0}t.running=false;t.startedAt=0;save();if(rerender)render()}
function resetTimer(){const t=db.timer;t.running=false;t.startedAt=0;t.endAt=0;t.elapsed=0;t.duration=t.mode==='break'?db.settings.breakMinutes*60:db.settings.focusMinutes*60;t.remaining=t.mode==='stopwatch'?0:t.duration;save();render()}
function recordSession(sec){if(sec<=0)return;const task=db.tasks.find(x=>x.id===db.timer.taskId);db.sessions.unshift({id:uid(),date:today(),startedAt:Date.now()-sec*1000,seconds:sec,task:task?.title||'',taskId:db.timer.taskId||''})}
function finishTimer(manual=false){const t=db.timer;let sec=t.mode==='stopwatch'?(t.elapsed+(t.running?Math.floor((Date.now()-t.startedAt)/1000):0)):t.duration-rem();if(t.mode==='focus'||t.mode==='stopwatch')recordSession(Math.max(0,sec));t.running=false;t.startedAt=0;t.endAt=0;t.elapsed=0;if(t.mode==='focus'&&!manual){t.rounds++;t.mode='break';t.duration=db.settings.breakMinutes*60;t.remaining=t.duration;t.endAt=Date.now()+t.remaining*1000;t.startedAt=Date.now();t.running=true;if(db.settings.alerts)toast('Focus block complete. Take a short break.')}else if(t.mode==='break'&&!manual){t.mode='focus';t.duration=db.settings.focusMinutes*60;t.remaining=t.duration;if(db.settings.alerts)toast('Break is over. Start when you’re ready.')}else{t.duration=(t.mode==='break'?db.settings.breakMinutes:db.settings.focusMinutes)*60;t.remaining=t.mode==='stopwatch'?0:t.duration;if(db.settings.alerts)toast(sec?'Session saved':'Timer finished')}save();render()}
function startTicker(){if(timerLoop)return;timerLoop=setInterval(()=>{const face=$('timer-face');if(!face)return;if(db.timer.running&&db.timer.mode!=='stopwatch'&&rem()<=0){finishTimer(false);return}face.textContent=clock(rem());const s=$('timer-subtitle');if(s&&db.timer.running)s.textContent='Session in progress'},250)}
function stopTicker(){if(timerLoop){clearInterval(timerLoop);timerLoop=null}}
function coachDraft(action){const topic=(view.querySelector('[name="coach-topic"]')?.value||'your topic').trim();db.ui.coachTopic=topic;let text='';if(action==='coach-break'){db.ui.coachTasks=[`Write down what you already know about ${topic}`,`Read one section and note three key ideas`, `Close your notes and recall the main idea`, `Try one representative practice question`];text=`A gentle first draft for “${topic}”\n\n1. Recall what you already know (5 min)\n2. Read one section and note 3 key ideas\n3. Close your notes and explain the main idea\n4. Try one practice question\n5. Add one point to revisit\n\nAdjust this plan to fit your actual chapter.`}else if(action==='coach-questions')text=`Recall prompts for “${topic}”\n\n• What is the central idea, in your own words?\n• Which terms or steps are easiest to confuse?\n• Can you give an example without looking at your notes?\n• What would change if one key assumption changed?\n\nThese are generic prompts, not verified subject questions.`;else if(action==='coach-checklist')text=`Revision checklist · “${topic}”\n\n□ Explain it without notes\n□ Check definitions and steps against your material\n□ Solve one representative problem\n□ Write down one question to ask\n□ Schedule a short recall session for tomorrow\n\nThis template does not verify course facts.`;else{const ex=db.exams.filter(e=>e.date>=today()).sort((a,b)=>a.date.localeCompare(b.date))[0];text=ex?`Next exam: ${ex.subject} in ${daysTo(ex.date)} days.\n\nTry one 25-minute block on an unfinished topic today, then leave a short recall session for tomorrow.\n\nAdjust this rule-based suggestion around your real availability.`:'Add an upcoming exam for a date-based preparation suggestion. You can also schedule one short focus block for an unfinished topic today.'}db.ui.coachText=text;save();render()}
function act(action,el){const id=el.dataset.id;switch(action){case'task-new':openForm('task');break;case'schedule-new':openForm('schedule');break;case'revision-new':openForm('revision');break;case'note-new':openForm('note');break;case'exam-new':openForm('exam');break;case'subject-new':openForm('subject');break;case'topic-new':openForm('topic','',{subjectId:id});break;case'task-edit':openForm('task',id);break;case'schedule-edit':openForm('schedule',id);break;case'note-edit':openForm('note',id);break;case'exam-edit':openForm('exam',id);break;case'task-delete':deleteItem('tasks',id,'task');break;case'schedule-delete':deleteItem('schedule',id,'study session');break;case'note-delete':deleteItem('notes',id,'note');break;case'exam-delete':deleteItem('exams',id,'exam');break;case'subject-delete':if(confirm('Delete this subject and all its chapters and topics?')){db.subjects=db.subjects.filter(s=>s.id!==id);save();render();toast('Subject deleted')}break;case'topic-delete':for(const s of db.subjects)for(const c of s.chapters)c.topics=c.topics.filter(t=>t.id!==id);save();render();toast('Topic deleted');break;case'revision-done':revisionDone(id);break;case'revision-reopen':{const r=db.revisions.find(x=>x.id===id);if(r){r.lastReview='';r.due=today();save();render()}}break;case'range':db.ui.range=el.dataset.range;save();render();break;case'navigate':db.ui.page=el.dataset.page||id||'dashboard';save();render();resetScroll();break;case'start-study':db.ui.page='focus';if(db.timer.running)render();else startTimer();resetScroll();break;case'timer-mode':setMode(el.dataset.mode);break;case'focus-mode':document.body.classList.toggle('immersive');render();break;case'timer-start':startTimer();break;case'timer-pause':pauseTimer();break;case'timer-reset':resetTimer();break;case'timer-finish':finishTimer(true);break;case'goals-edit':openForm('goals');break;case'coach-break':case'coach-questions':case'coach-checklist':case'coach-plan':coachDraft(action);break;case'coach-save':if(db.ui.coachTasks?.length){const subject=db.ui.coachTopic||'';db.ui.coachTasks.forEach(title=>db.tasks.unshift({id:uid(),title,subject,description:'Suggested by the local study coach. Check against your course plan.',dueDate:'',priority:'medium',estimate:20,completed:false,createdAt:Date.now()}));db.ui.page='tasks';save();render();toast('Coach steps added to tasks')}break;case'export':exportData();break;case'clear-data':clearData();break;case'close-more':$('more-dialog').close();break;case'close-modal':modal.close();break}}
const plannerAct=act;
act=function(action,el){switch(action){case'sync-signup':syncAuth('signup');return;case'sync-signin':syncAuth('signin');return;case'sync-signout':Sync.signOut().then(()=>{syncSession=null;syncPending=null;syncMessage='Signed out. This device’s planner data was kept.';render()}).catch(()=>{syncSession=null;syncPending=null;syncMessage='Signed out locally. This device’s planner data was kept.';render()});return;case'sync-preview':reviewSync();return;case'sync-upload':syncUpload();return;case'sync-download':syncDownload();return;case'sync-export':if(syncPending?.remote)downloadWorkspace(syncPending.remote.workspace,'cloud-backup');return;case'sync-delete':syncDelete();return;case'sync-clear-config':if(confirm('Remove this browser’s provider settings and sign out? Planner data stays on this device and cloud data is unchanged.')){Sync.clearSyncConfig();syncSession=null;syncPending=null;syncMessage='Provider settings removed. Local planner data was kept.';render()}return;default:plannerAct(action,el)}};
const plannerSyncAct=act;
act=function(action,el){if(action!=='sync-signout')return plannerSyncAct(action,el);const pending=Sync.signOut();syncSession=null;syncPending=null;syncMessage='Signed out. This device’s planner data was kept.';render();pending.catch(()=>{syncMessage='Signed out locally. This device’s planner data was kept.';render()})};
document.addEventListener('submit',e=>{if(e.target.id!=='sync-config-form')return;e.preventDefault();try{Sync.clearSession();Sync.saveSyncConfig({url:$('f-sync-url').value,publicKey:$('f-sync-public-key').value});syncSession=null;syncPending=null;syncMessage='Provider settings saved. No planner data was uploaded.';render()}catch(error){syncMessage=error.message||'Provider settings were not saved.';render()}});
function onClick(e){const nav=e.target.closest('[data-page]');if(nav){const page=nav.dataset.page;if(page==='more'){$('more-dialog').showModal();return}if(titles[page]){if(document.getElementById("more-dialog").open)document.getElementById("more-dialog").close();db.ui.page=page;save();render();resetScroll();return}}const a=e.target.closest('[data-action]');if(a)act(a.dataset.action,a)}
document.addEventListener('click',onClick);
document.addEventListener('change',e=>{const x=e.target;if(x.dataset.action==='task-toggle'){toggleTask(x.dataset.id,x.checked);return}if(x.dataset.action==='note-check'){const n=db.notes.find(y=>y.id===x.dataset.id),c=n?.checklist?.[+x.dataset.index];if(c){c.done=x.checked;save();render()}return}switch(x.dataset.change){case'date':db.ui.date=x.value||today();save();render();break;case'status':db.ui.status=x.value;save();render();break;case'priority':db.ui.priority=x.value;save();render();break;case'task-subject':db.ui.taskSubject=x.value;save();render();break;case'task-due':db.ui.taskDue=x.value;save();render();break;case'topic-status':{const s=db.subjects.find(y=>y.id===x.dataset.subject),c=s?.chapters.find(y=>y.id===x.dataset.chapter),t=c?.topics.find(y=>y.id===x.dataset.topic);if(t){t.status=x.value;t.completedAt=x.value==='completed'?today():'';save();render()}break}case'alerts':db.settings.alerts=x.checked;save();toast('Preference saved');break}if(x.name==='taskId'){db.timer.taskId=x.value;save()}if(x.id==='import-file')importData(x.files?.[0]);if(x.name==='focus-length'){db.settings.focusMinutes=Math.max(1,Math.min(180,+x.value||25));if(!db.timer.running&&db.timer.mode==='focus'){db.timer.duration=db.settings.focusMinutes*60;db.timer.remaining=db.timer.duration}save();render()}});
document.addEventListener('input',e=>{const x=e.target;if(x.dataset.input==='task-query'||x.dataset.input==='note-query'){const key=x.dataset.input==='task-query'?'taskQuery':'noteQuery';db.ui[key]=x.value;const pos=x.selectionStart;render();const y=view.querySelector(`[data-input="${x.dataset.input}"]`);y?.focus();y?.setSelectionRange(pos,pos)}});
async function autoSaveNote(){if(formType!=='note')return;const v=n=>form.elements.namedItem(n)?.value?.trim()||'',title=v('title');if(!title)return;const url=v('url');if(url&&safeLink(url)==='#'){$('modal-error').textContent='Use a valid http or https link.';$('modal-error').classList.remove('saved');return}let note=editId?db.notes.find(x=>x.id===editId):null;if(!note){note={id:editId||uid(),title,subject:'',chapter:'',topic:'',url:'',body:'',checklist:[],createdAt:Date.now()};editId=note.id;db.notes.unshift(note)}const lines=v('checklist').split(/\r?\n/).map(x=>x.trim()).filter(Boolean);Object.assign(note,{title,subject:v('subject'),chapter:v('chapter'),topic:v('topic'),url,body:v('body'),checklist:lines.map(text=>({text,done:note.checklist?.find(x=>x.text===text)?.done||false}))});$('modal-error').textContent='Saving locally…';$('modal-error').classList.add('saved');const ok=await save();$('modal-error').textContent=ok?'Saved on this device':'Could not save';if(!ok)$('modal-error').classList.remove('saved')}
document.addEventListener('input',e=>{if(formType==='note'&&form.contains(e.target)){clearTimeout(noteAutosave);noteAutosave=setTimeout(autoSaveNote,500)}});document.addEventListener('submit',e=>{if(e.target.id==='settings-form'){e.preventDefault();const f=e.target;db.profile.name=f.elements.profileName.value.trim()||'Student';db.profile.language=f.elements.language.value;db.settings.focusMinutes=Math.max(1,Math.min(180,+f.elements.focusMinutes.value||25));db.settings.breakMinutes=Math.max(1,Math.min(60,+f.elements.breakMinutes.value||5));if(!db.timer.running&&db.timer.mode!=='stopwatch'){db.timer.duration=db.settings.focusMinutes*60;db.timer.remaining=db.timer.duration}save();render();toast('Preferences saved')}});
$('theme-toggle').addEventListener('click',()=>{db.settings.theme=db.settings.theme==='dark'?'light':'dark';save();shell()});$('mobile-menu').addEventListener('click',()=>$('more-dialog').showModal());
$('modal').addEventListener('click',e=>{if(e.target===modal)modal.close()});$('more-dialog').addEventListener('click',e=>{if(e.target===$('more-dialog'))e.target.close()});
function exportData(){const blob=new Blob([JSON.stringify({app:'FocusFlow',version:2,exportedAt:new Date().toISOString(),data:db},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`focusflow-backup-${today()}.json`;document.body.append(a);a.click();a.remove();URL.revokeObjectURL(url);toast('Planner backup downloaded')}
async function importData(file){if(!file)return;if(file.size>MAX_BACKUP_BYTES){toast('Backup files must be 5 MB or smaller.');return}const reader=new FileReader();reader.onload=async()=>{try{const next=parseBackup(reader.result),replacement=normalizeWorkspace({...fresh(),...next,version:2});if(!confirm('Replace this browser’s planner data with the selected backup?'))return;const previous=db;db=replacement;if(!await save()){db=previous;return}render();toast('Backup restored')}catch(e){toast(e.message||'Could not read that backup')}};reader.onerror=()=>toast('Could not read the selected backup.');reader.readAsText(file)}
async function clearData(){if(!confirm('Clear all FocusFlow tasks, notes, sessions, and plans from this browser? Export a backup first if you may need it later.'))return;await Store.clearWorkspace();db=fresh();await save();render();toast('Planner data cleared')}
modal.querySelectorAll('[data-action="close-modal"]').forEach(x=>x.addEventListener('click',()=>modal.close()));form.addEventListener('submit',saveForm);
function normalizeWorkspace(data){const base=fresh(),out={...base,...data,profile:{...base.profile,...data?.profile},settings:{...base.settings,...data?.settings},goals:{...base.goals,...data?.goals},timer:{...base.timer,...data?.timer},ui:{...base.ui,...data?.ui}};for(const k of ['tasks','schedule','sessions','notes','revisions','subjects','exams'])if(!Array.isArray(out[k]))out[k]=[];out.tasks=out.tasks.filter(t=>t&&typeof t.title==='string').map(t=>({...t,priority:['low','medium','high'].includes(t.priority)?t.priority:'medium',completed:!!t.completed,estimate:t.estimate||30}));out.subjects=out.subjects.filter(s=>s&&typeof s.name==='string').map(s=>({...s,chapters:Array.isArray(s.chapters)?s.chapters.filter(c=>c&&typeof c.title==='string').map(c=>({...c,topics:Array.isArray(c.topics)?c.topics.filter(t=>t&&typeof t.title==='string'):[]})):[]}));return out}
function updateNetwork(){const x=$('network-status');if(x){x.hidden=navigator.onLine;x.textContent=navigator.onLine?'':'Offline · your plans stay on this device';x.classList.toggle('offline',!navigator.onLine)}}
async function setupOffline(){updateNetwork();addEventListener('online',updateNetwork);addEventListener('offline',updateNetwork);if('serviceWorker'in navigator&&(location.protocol==='https:'||location.hostname==='localhost'||location.hostname==='127.0.0.1')){try{const reg=await navigator.serviceWorker.register('./sw.js',{scope:'./',updateViaCache:'none'});reg.update().catch(()=>{});reg.addEventListener('updatefound',()=>{const w=reg.installing;w?.addEventListener('statechange',()=>{if(w.state==='installed'&&navigator.serviceWorker.controller)toast('FocusFlow is updated and ready offline.')})})}catch(e){console.warn('Offline app shell could not be registered.',e)}}}
async function initialize(){try{const saved=await Store.loadWorkspace(fresh());db=normalizeWorkspace(parseBackup(JSON.stringify(saved)))}catch(e){console.error('Workspace load failed.',e);db=fresh();toast('Your workspace could not be loaded. Existing saved values were not changed.')}if(db.timer.running&&db.timer.mode!=='stopwatch'&&db.timer.endAt<=Date.now()){db.timer.running=false;db.timer.remaining=0;save()}render();setupOffline()}
const initializeLocal=initialize;
initialize=async function(){const onGithubPages=location.hostname.toLowerCase().endsWith('.github.io');if(onGithubPages){Sync.clearSession();syncSession=null} else syncSession=Sync.sessionSnapshot();const warning=$('github-origin-warning');if(warning&&onGithubPages)warning.hidden=false;await initializeLocal()};
initialize();
})();
